// Audit shim: `ws`-compatible wrapper around Node's global (undici) WebSocket,
// which routes through the sandbox egress proxy. Only the surface
// lib/reliks-lib.js uses: constructor(url, {headers}), .on('open'|'message'|'error'|'close'), .send(), .close(), .terminate().
const { EventEmitter } = require('events');
class WS extends EventEmitter {
  constructor(url) {
    super();
    const inner = new globalThis.WebSocket(url);
    this._inner = inner;
    inner.onopen = () => this.emit('open');
    inner.onmessage = (ev) => this.emit('message', Buffer.from(typeof ev.data === 'string' ? ev.data : ev.data));
    inner.onerror = (ev) => this.emit('error', new Error(ev.message || 'websocket error'));
    inner.onclose = () => this.emit('close');
  }
  send(data) { this._inner.send(data); }
  close() { try { this._inner.close(); } catch (e) {} }
  terminate() { this.close(); }
}
module.exports = WS;
